<?php

declare(strict_types=1);

namespace App\Api\Communication;

use App\Contracts\Domains\ApiSender;
use App\Data\Messages\MessageView;
use App\Support\CallKey;

/**
 * The API of Communication, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class CommunicationApi
{
    public function __construct(private ApiSender $sender) {}

    public function readMessage(
        string $messageId,
        CallKey $requestKey = new CallKey(),
    ): MessageView {
        return $this->sender->send(ReadMessagePayload::from(['messageId' => $messageId, 'requestKey' => $requestKey]));
    }

    public function readUnreadMessages(
        CallKey $requestKey = new CallKey(),
    ): UnreadMessages {
        return $this->sender->send(ReadUnreadMessagesPayload::from(['requestKey' => $requestKey]));
    }

    public function sendMessage(
        NewMessage $message,
        CallKey $requestKey = new CallKey(),
    ): MessageNamed {
        return $this->sender->send(SendMessagePayload::from(['message' => $message, 'requestKey' => $requestKey]));
    }
}
